  3→/// A simple table for formatted output.
  4→#[derive(Debug)]
  5→pub struct Table {
  6→    headers: Vec<String>,
  7→    rows: Vec<Vec<String>>,
  8→    column_widths: Vec<usize>,
  9→}
 10→
 11→impl Table {
 12→    /// Create a new table with the given headers.
 13→    pub fn new(headers: Vec<&str>) -> Self {
 14→        let headers: Vec<String> = headers.iter().map(|s| s.to_string()).collect();
 15→        let column_widths = headers.iter().map(|h| h.len()).collect();
 16→
 17→        Self {
 18→            headers,
 19→            rows: Vec::new(),
 20→            column_widths,
 21→        }
 22→    }
 23→
 24→    /// Add a row to the table.
 25→    pub fn add_row(&mut self, row: Vec<&str>) {
 26→        let row: Vec<String> = row.iter().map(|s| s.to_string()).collect();
 27→
 28→        // Update column widths
 29→        for (i, cell) in row.iter().enumerate() {
 30→            if i < self.column_widths.len() {
 31→                self.column_widths[i] = self.column_widths[i].max(cell.len());
 32→            }
 33→        }
 34→
 35→        self.rows.push(row);
 36→    }
 37→
 38→    /// Get the number of rows.
 39→    pub fn row_count(&self) -> usize {
 40→        self.rows.len()
 41→    }
 42→
 43→    /// Check if the table is empty.
 44→    pub fn is_empty(&self) -> bool {
 45→        self.rows.is_empty()
 46→    }
 47→
 48→    /// Render the table as a string.
 49→    pub fn render(&self) -> String {
 50→        let mut output = String::new();
 51→
 52→        // Top border
 53→        output.push_str(&self.render_border('┌', '┬', '┐'));
 54→        output.push('\n');
 55→
 56→        // Header row
 57→        output.push_str(&self.render_row(&self.headers));
 58→        output.push('\n');
 59→
 60→        // Header separator
 61→        output.push_str(&self.render_border('├', '┼', '┤'));
 62→        output.push('\n');
 63→
 64→        // Data rows
 65→        for row in &self.rows {
 66→            output.push_str(&self.render_row(row));
 67→            output.push('\n');
 68→        }
 69→
 70→        // Bottom border
 71→        output.push_str(&self.render_border('└', '┴', '┘'));
 72→
 73→        output
 74→    }
 75→
 76→    fn render_border(&self, left: char, mid: char, right: char) -> String {
 77→        let mut s = String::new();
 78→        s.push(left);
 79→
 80→        for (i, width) in self.column_widths.iter().enumerate() {
 81→            s.push_str(&"─".repeat(width + 2));
 82→            if i < self.column_widths.len() - 1 {
 83→                s.push(mid);
 84→            }
 85→        }
 86→
 87→        s.push(right);
 88→        s
 89→    }
 90→
 91→    fn render_row(&self, row: &[String]) -> String {
 92→        let mut s = String::from("│");
 93→
 94→        for (i, width) in self.column_widths.iter().enumerate() {
 95→            let cell = row.get(i).map(|s| s.as_str()).unwrap_or("");
 96→            s.push_str(&format!(" {:width$} │", cell, width = width));
 97→        }
 98→
 99→        s
100→    }
101→}
