260→/// Spinner that does nothing (for non-interactive mode).
261→struct NoopSpinner {
262→    indent: usize,
263→}
264→
265→impl SpinnerHandle for NoopSpinner {
266→    fn set_message(&mut self, _msg: &str) {}
267→
268→    fn finish_success(&mut self, msg: &str) {
269→        let prefix = " ".repeat(self.indent);
270→        let theme = BivvyTheme::new();
271→        println!("{}{}", prefix, theme.format_success(msg));
272→    }
273→
274→    fn finish_error(&mut self, msg: &str) {
275→        let prefix = " ".repeat(self.indent);
276→        let theme = BivvyTheme::new();
277→        println!("{}{}", prefix, theme.format_error(msg));
278→    }
279→
280→    fn finish_skipped(&mut self, msg: &str) {
281→        let prefix = " ".repeat(self.indent);
282→        let theme = BivvyTheme::new();
283→        println!("{}{}", prefix, theme.format_skipped(msg));
284→    }
285→}
