 47→impl Command for ListCommand {
 48→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 49→        // Load configuration
 50→        let config = match load_merged_config(&self.project_root) {
 51→            Ok(c) => c,
 52→            Err(BivvyError::ConfigNotFound { .. }) => {
 53→                ui.error("No configuration found. Run 'bivvy init' first.");
 54→                return Ok(CommandResult::failure(2));
 55→            }
 56→            Err(e) => return Err(e),
 57→        };
 58→
 59→        // Apply config default_output when no CLI flag was explicitly set
 60→        if ui.output_mode() == OutputMode::Normal {
 61→            ui.set_output_mode(config.settings.default_output.into());
 62→        }
 63→
 64→        let theme = BivvyTheme::new();
 65→
 66→        // Resolve environment
 67→        let resolved_env = self.resolve_environment(&config);
 68→        let env_name = &resolved_env.name;
 69→
