 83→                let skipped = !step.only_environments.is_empty()
 84→                    && !step.only_environments.iter().any(|e| e == env_name);
 85→
 86→                if skipped {
 87→                    ui.message(&format!(
 88→                        "    {} {}",
 89→                        theme.dim.apply_to(name),
 90→                        theme.dim.apply_to(format!("(skipped in {})", env_name)),
 91→                    ));
 92→                    continue;
 93→                }
 94→
 95→                // First line: step name with template/command detail
