102→                    format!(
103→                        " {} {}",
104→                        theme.dim.apply_to("—"),
105→                        theme.command.apply_to(cmd)
106→                    )
107→                } else {
108→                    String::new()
109→                };
110→                ui.message(&format!("    {}{}", theme.highlight.apply_to(name), detail));
111→
112→                // Description or title
113→                if let Some(ref desc) = step.description {
114→                    ui.message(&format!("      {}", theme.dim.apply_to(desc)));
115→                } else if let Some(ref title) = step.title {
116→                    ui.message(&format!("      {}", theme.dim.apply_to(title)));
117→                }
118→
119→                // Dependency tree
120→                if !step.depends_on.is_empty() {
121→                    ui.message(&format!(
122→                        "      {} {}",
