388→/// Mock spinner that captures finish messages.
389→#[derive(Debug, Default)]
390→pub struct MockSpinner {
391→    messages: Vec<String>,
392→    finish_message: Option<String>,
393→    status: Option<SpinnerStatus>,
394→}
395→
396→/// Status of a mock spinner when finished.
397→#[derive(Debug, Clone, Copy, PartialEq)]
398→pub enum SpinnerStatus {
399→    /// Finished successfully.
400→    Success,
401→    /// Finished with error.
402→    Error,
403→    /// Finished as skipped.
404→    Skipped,
405→}
406→
407→impl MockSpinner {
408→    /// Create a new mock spinner.
409→    pub fn new() -> Self {
410→        Self::default()
411→    }
412→
413→    /// Get all messages set during spinning.
414→    pub fn messages(&self) -> &[String] {
415→        &self.messages
416→    }
417→
418→    /// Get the final finish message.
419→    pub fn finish_message(&self) -> Option<&str> {
420→        self.finish_message.as_deref()
421→    }
422→
423→    /// Get the final status.
424→    pub fn status(&self) -> Option<SpinnerStatus> {
425→        self.status
426→    }
427→}
428→
429→impl SpinnerHandle for MockSpinner {
430→    fn set_message(&mut self, msg: &str) {
431→        self.messages.push(msg.to_string());
432→    }
433→
434→    fn finish_success(&mut self, msg: &str) {
435→        self.finish_message = Some(msg.to_string());
436→        self.status = Some(SpinnerStatus::Success);
437→    }
438→
439→    fn finish_error(&mut self, msg: &str) {
440→        self.finish_message = Some(msg.to_string());
441→        self.status = Some(SpinnerStatus::Error);
442→    }
443→
444→    fn finish_skipped(&mut self, msg: &str) {
445→        self.finish_message = Some(msg.to_string());
446→        self.status = Some(SpinnerStatus::Skipped);
447→    }
448→}
