//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands (`::error::`,
//! `::warning::`, `::notice::`) so they appear as annotations in pull request
//! diffs and the Actions summary page.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic is emitted as a `::error::`, `::warning::`, or `::notice::`
/// command with optional `file`, `line`, `col`, and `title` parameters.
///
/// # Example output
///
/// ```text
/// ::error file=config.yml,line=10,col=5,title=circular-dependency::Circular dependency detected
/// ::warning file=config.yml,line=3,title=app-name::App name contains spaces
/// ```
pub struct GithubFormatter;

impl GithubFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl LintFormatter for GithubFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_command(diag.severity);

            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));
                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");
            writeln!(writer, "::{command} {params_str}::{}", diag.message)?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_as_workflow_command() {
        let formatter = GithubFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency detected",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=10,title=circular-dependency::Circular dependency detected\n"
        );
    }

    #[test]
    fn formats_warning_as_workflow_command() {
        let formatter = GithubFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("app-name"),
            Severity::Warning,
            "App name contains spaces",
        )
        .with_span(Span::line("config.yml", 3))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::warning file=config.yml,line=3,title=app-name::App name contains spaces\n"
        );
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GithubFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("style-hint"),
            Severity::Hint,
            "Consider using kebab-case",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::notice title=style-hint::Consider using kebab-case\n"
        );
    }

    #[test]
    fn includes_column_when_greater_than_one() {
        let formatter = GithubFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test-rule"), Severity::Error, "Bad value")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=10,col=5,title=test-rule::Bad value\n"
        );
    }

    #[test]
    fn omits_file_params_without_span() {
        let formatter = GithubFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("global-rule"),
            Severity::Error,
            "Global issue",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(output, "::error title=global-rule::Global issue\n");
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("rule-a"), Severity::Error, "First error")
                .with_span(Span::line("config.yml", 1)),
            LintDiagnostic::new(RuleId::new("rule-b"), Severity::Warning, "A warning")
                .with_span(Span::line("config.yml", 5)),
            LintDiagnostic::new(RuleId::new("rule-c"), Severity::Hint, "A hint"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 3);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
        assert!(lines[2].starts_with("::notice "));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
        let formatter = GithubFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }
}
